import{c as e,Q as r,j as d,m as o}from"./chunks/framework.8JjYC3xy.js";const p=JSON.parse('{"title":"关于本教程","description":"这份教程对齐到哪个版本、怎么判断内容是否过时、已知未覆盖的范围","frontmatter":{"title":"关于本教程","description":"这份教程对齐到哪个版本、怎么判断内容是否过时、已知未覆盖的范围","lastVerified":"2026-02-24","officialDoc":"https://code.claude.com/docs/zh-CN/overview"},"headers":[],"relativePath":"guide/about.md","filePath":"guide/about.md"}'),a={name:"guide/about.md"};function l(c,t,s,n,h,i){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="关于本教程" tabindex="-1">关于本教程 <a class="header-anchor" href="#关于本教程" aria-label="Permalink to &quot;关于本教程&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">一句话</p><p>本教程按<strong>官方文档 2026-02-24 的快照</strong>校对，对应 Claude Code <strong>v2.1.x</strong>。每篇文章底部都标了它自己的最后核对日期。</p></div><h2 id="为什么需要这一页" tabindex="-1">为什么需要这一页 <a class="header-anchor" href="#为什么需要这一页" aria-label="Permalink to &quot;为什么需要这一页&quot;">​</a></h2><p>Claude Code 更新非常快：新功能、新的默认行为、甚至术语改名（比如&quot;Agent 模式&quot;已经并入&quot;权限模式&quot;）几个月就会变一轮。</p><p>所以这份教程不再假装&quot;永远正确&quot;，而是明确告诉你：<strong>哪一天对过的、对着哪个版本对的</strong>。</p><h2 id="怎么判断一篇内容是否过时" tabindex="-1">怎么判断一篇内容是否过时 <a class="header-anchor" href="#怎么判断一篇内容是否过时" aria-label="Permalink to &quot;怎么判断一篇内容是否过时&quot;">​</a></h2><p>三步，30 秒：</p><ol><li>看文章底部的「本文最后按官方文档核对」</li><li>如果超过 <strong>3 个月</strong>，把它当&quot;可能过时&quot;对待</li><li>点同一行的「查看官方原文 ↗」，用官方最新说法覆盖本文</li></ol><p>不确定的地方<strong>永远以官方原文为准</strong>，本文只是更容易读的转述。</p><h2 id="全站核对状态" tabindex="-1">全站核对状态 <a class="header-anchor" href="#全站核对状态" aria-label="Permalink to &quot;全站核对状态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>篇章</th><th>最后核对</th></tr></thead><tbody><tr><td>入门篇（第 1-4 章）</td><td>2026-02-24</td></tr><tr><td>基础篇（第 5-7 章）</td><td>2026-02-24</td></tr><tr><td>实战篇（第 8-12 章）</td><td>2026-02-24</td></tr><tr><td>高阶篇（第 13-19 章）</td><td>2026-02-24</td></tr><tr><td>速查表</td><td>2026-02-24</td></tr></tbody></table><h2 id="每章对应的官方页" tabindex="-1">每章对应的官方页 <a class="header-anchor" href="#每章对应的官方页" aria-label="Permalink to &quot;每章对应的官方页&quot;">​</a></h2><p>想深入某个主题，直接看官方原文最准：</p><table tabindex="0"><thead><tr><th>本教程</th><th>官方页</th></tr></thead><tbody><tr><td>第 1 章 是什么</td><td><a href="https://code.claude.com/docs/zh-CN/overview" target="_blank" rel="noreferrer">概述</a></td></tr><tr><td>第 2 章 安装</td><td><a href="https://code.claude.com/docs/zh-CN/setup" target="_blank" rel="noreferrer">安装与设置</a></td></tr><tr><td>第 3 章 第三方中转</td><td><a href="https://code.claude.com/docs/zh-CN/authentication" target="_blank" rel="noreferrer">身份验证</a></td></tr><tr><td>第 4 章 首次对话</td><td><a href="https://code.claude.com/docs/zh-CN/quickstart" target="_blank" rel="noreferrer">快速开始</a></td></tr><tr><td>第 5 章 读懂代码库</td><td><a href="https://code.claude.com/docs/zh-CN/how-claude-code-works" target="_blank" rel="noreferrer">Claude Code 如何工作</a></td></tr><tr><td>第 6 章 编辑代码</td><td><a href="https://code.claude.com/docs/zh-CN/common-workflows" target="_blank" rel="noreferrer">常见工作流</a></td></tr><tr><td>第 7 章 上下文与会话</td><td><a href="https://code.claude.com/docs/zh-CN/sessions" target="_blank" rel="noreferrer">管理会话</a></td></tr><tr><td>第 8 章 调试</td><td><a href="https://code.claude.com/docs/zh-CN/troubleshooting" target="_blank" rel="noreferrer">故障排查</a></td></tr><tr><td>第 9 章 代码审查</td><td><a href="https://code.claude.com/docs/zh-CN/code-review" target="_blank" rel="noreferrer">代码审查</a></td></tr><tr><td>第 10 章 Git</td><td><a href="https://code.claude.com/docs/zh-CN/common-workflows" target="_blank" rel="noreferrer">常见工作流</a></td></tr><tr><td>第 11 章 CLAUDE.md</td><td><a href="https://code.claude.com/docs/zh-CN/memory" target="_blank" rel="noreferrer">记忆</a></td></tr><tr><td>第 12 章 一天实战</td><td><a href="https://code.claude.com/docs/zh-CN/best-practices" target="_blank" rel="noreferrer">最佳实践</a></td></tr><tr><td>第 13 章 MCP</td><td><a href="https://code.claude.com/docs/zh-CN/mcp" target="_blank" rel="noreferrer">MCP</a></td></tr><tr><td>第 14 章 Skill</td><td><a href="https://code.claude.com/docs/zh-CN/skills" target="_blank" rel="noreferrer">Skills</a></td></tr><tr><td>第 15 章 命令</td><td><a href="https://code.claude.com/docs/zh-CN/commands" target="_blank" rel="noreferrer">命令参考</a></td></tr><tr><td>第 16 章 Hooks</td><td><a href="https://code.claude.com/docs/zh-CN/hooks" target="_blank" rel="noreferrer">Hooks</a></td></tr><tr><td>第 17 章 权限模式</td><td><a href="https://code.claude.com/docs/zh-CN/permission-modes" target="_blank" rel="noreferrer">权限模式</a></td></tr><tr><td>第 18 章 GitHub Actions</td><td><a href="https://code.claude.com/docs/zh-CN/github-actions" target="_blank" rel="noreferrer">GitHub Actions</a></td></tr><tr><td>第 19 章 Subagents</td><td><a href="https://code.claude.com/docs/zh-CN/sub-agents" target="_blank" rel="noreferrer">Subagents</a></td></tr><tr><td>速查表</td><td><a href="https://code.claude.com/docs/zh-CN/commands" target="_blank" rel="noreferrer">命令参考</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">一个官方提供的便利</p><p>官方站点支持在任意页面地址后加 <code>.md</code> 直接拿到干净的 Markdown 原文，例如 <code>https://code.claude.com/docs/zh-CN/overview.md</code>。想复制内容进 AI 里讨论时很方便。</p></div><h2 id="已知未覆盖-诚实清单" tabindex="-1">已知未覆盖（诚实清单） <a class="header-anchor" href="#已知未覆盖-诚实清单" aria-label="Permalink to &quot;已知未覆盖（诚实清单）&quot;">​</a></h2><p>这些是当前版本存在、但本教程还没单独成章的内容：</p><ul><li><strong>插件与 Marketplace</strong>（<code>/plugin</code>、添加 marketplace）— 计划中</li><li><strong>多端形态</strong>：桌面应用、VS Code / JetBrains 扩展、网页版与云端会话、手机 Remote Control</li><li><strong>Agent Teams / 后台会话管理</strong>（<code>claude agents</code>）</li><li><strong>企业级配置</strong>：托管设置、SSO、云厂商（Bedrock / Vertex / Foundry）接入</li><li><strong>Agent SDK</strong>：把 Claude Code 当库来编程</li></ul><p>覆盖优先级按&quot;国内日常用户会不会用到&quot;排，所以越靠前越可能先写。</p><h2 id="教程的取舍" tabindex="-1">教程的取舍 <a class="header-anchor" href="#教程的取舍" aria-label="Permalink to &quot;教程的取舍&quot;">​</a></h2><p>这份教程不是官方文档的中文翻译，刻意做了这些取舍：</p><ul><li><strong>只讲日常用得上的</strong>，冷门参数不展开，需要时查官方</li><li><strong>面向中国大陆用户</strong>：网络、支付、中转的实际问题都写出来，哪怕官方文档不涉及</li><li><strong>默认读者没写过命令行</strong>：术语第一次出现时都会解释</li><li><strong>不追版本号</strong>：模型一律用 <code>opus</code> / <code>sonnet</code> / <code>haiku</code> 别名，避免写完就过时</li></ul><h2 id="发现错误怎么办" tabindex="-1">发现错误怎么办 <a class="header-anchor" href="#发现错误怎么办" aria-label="Permalink to &quot;发现错误怎么办&quot;">​</a></h2><p>如果某段内容和官方对不上，以官方为准，并顺手提交一个 issue 或 PR —— 页面底部的链接就是用来核对这一点的。</p>',24)])])}const m=e(a,[["render",l]]);export{p as __pageData,m as default};
